    {
      "name": "导数",
      "aliases": ["derivative", "导函数"],
      "definition_snippet": "函数在某点处的变化率，记作 f'(x)。",
      "category": "concept"
    },
    {
      "name": "极限",
      "aliases": ["limit", "极限运算"],
      "definition_snippet": "导数定义与导数运算法则的基础。",
      "category": "concept"
    },
    {
      "name": "可导函数",
      "aliases": ["differentiable function", "可导的函数"],
      "definition_snippet": "在所讨论范围内存在导数的函数。",
      "category": "concept"
    },
    {
      "name": "基本初等函数",
      "aliases": ["basic elementary function", "初等函数"],
      "definition_snippet": "常数、幂、三角、指数、对数等基本函数。",
      "category": "concept"
    },
    {
      "name": "常数函数",
      "aliases": ["constant function", "常量函数"],
      "definition_snippet": "形如 y=C 的函数，其导数为 0。",
      "category": "concept"
    },
    {
      "name": "幂函数",
      "aliases": ["power function", "x^n 函数"],
      "definition_snippet": "形如 y=x^n 的函数，其导数为 nx^(n-1)。",
      "category": "concept"
    },
    {
      "name": "正弦函数",
      "aliases": ["sine function", "sin x"],
      "definition_snippet": "y=sin x，其导数为 cos x。",
      "category": "concept"
    },
    {
      "name": "余弦函数",
      "aliases": ["cosine function", "cos x"],
      "definition_snippet": "y=cos x，其导数为 -sin x。",
      "category": "concept"
    },
    {
      "name": "指数函数",
      "aliases": ["exponential function", "a^x 函数"],
      "definition_snippet": "形如 y=a^x 的函数，其导数为 a^x ln a。",
      "category": "concept"
    },
    {
      "name": "对数函数",
      "aliases": ["logarithmic function", "log_a x 函数"],
      "definition_snippet": "形如 y=log_a x 的函数，其导数为 1/(x ln a)。",
      "category": "concept"
    },
    {
      "name": "自然指数函数",
      "aliases": ["natural exponential function", "e^x 函数"],
      "definition_snippet": "y=e^x，其导数为 e^x。",
      "category": "concept"
    },
    {
      "name": "自然对数函数",
      "aliases": ["natural logarithmic function", "ln x 函数"],
      "definition_snippet": "y=ln x，其导数为 1/x。",
      "category": "concept"
    },
    {
      "name": "导数公式",
      "aliases": ["derivative formulas", "基本初等函数导数公式"],
      "definition_snippet": "基本初等函数的导数结果汇总。",
      "category": "theorem"
    },
    {
      "name": "常数函数的导数公式",
      "aliases": ["derivative formula of constant function", "常数函数导数公式"],
      "definition_snippet": "(C)' = 0。",
      "category": "theorem"
    },
    {
      "name": "幂函数的导数公式",
      "aliases": ["derivative formula of power function", "幂函数导数公式"],
      "definition_snippet": "(x^n)' = nx^(n-1)。",
      "category": "theorem"
    },
    {
      "name": "正弦函数的导数公式",
      "aliases": ["derivative formula of sine function", "正弦函数导数公式"],
      "definition_snippet": "(sin x)' = cos x。",
      "category": "theorem"
    },
    {
      "name": "余弦函数的导数公式",
      "aliases": ["derivative formula of cosine function", "余弦函数导数公式"],
      "definition_snippet": "(cos x)' = -sin x。",
      "category": "theorem"
    },
    {
      "name": "指数函数的导数公式",
      "aliases": ["derivative formula of exponential function", "指数函数导数公式"],
      "definition_snippet": "(a^x)' = a^x · ln a。",
      "category": "theorem"
    },
    {
      "name": "对数函数的导数公式",
      "aliases": ["derivative formula of logarithmic function", "对数函数导数公式"],
      "definition_snippet": "(log_a x)' = 1/(x · ln a)。",
      "category": "theorem"
    },
    {
      "name": "自然指数函数的导数公式",
      "aliases": ["derivative formula of natural exponential function", "e^x 导数公式"],
      "definition_snippet": "(e^x)' = e^x。",
      "category": "theorem"
    },
    {
      "name": "自然对数函数的导数公式",
      "aliases": ["derivative formula of natural logarithmic function", "ln x 导数公式"],
      "definition_snippet": "(ln x)' = 1/x。",
      "category": "theorem"
    },
    {
      "name": "导数运算法则",
      "aliases": ["derivative operation rules", "导数四则运算法则"],
      "definition_snippet": "对可导函数进行求导的四则运算规则。",
      "category": "operation"
    },
    {
      "name": "导数的和差法则",
      "aliases": ["sum and difference rule", "和差法则"],
      "definition_snippet": "[u(x) ± v(x)]' = u'(x) ± v'(x)。",
      "category": "operation"
    },
    {
      "name": "导数的积法则",
      "aliases": ["product rule", "积法则"],
      "definition_snippet": "[u(x) · v(x)]' = u'(x)v(x) + u(x)v'(x)。",
      "category": "operation"
    },
    {
      "name": "导数的商法则",
      "aliases": ["quotient rule", "商法则"],
      "definition_snippet": "[u(x)/v(x)]' = [u'(x)v(x) - u(x)v'(x)] / [v(x)]²，其中 v(x) ≠ 0。",
      "category": "operation"
    },
    {
      "name": "多元乘积求导法则",
      "aliases": ["product rule for multiple functions", "多个函数乘积求导法则"],
      "definition_snippet": "多个函数相乘时逐项求导再相加，如 (uvw)' = u'vw + uv'w + uvw'。",
      "category": "operation"
    },
    {
      "name": "微分学",
      "aliases": ["differential calculus", "微积分"],
      "definition_snippet": "以导数及其运算法则为计算基础的数学分支。",
      "category": "concept"
    }
  ],
